"""Mindest- und Höchstfristen ausgewählter Verbrauchervertragsvereinbarungen."""
from .kalender import _auswahl, _datum, _ergebnis, _fehler, _frist, _text
_FAELLE = {'verbrauchsgut_neu_mindestverjaehrung': (2, 'jahre', 'mindestens', '§476 Absatz2: gesetzlicher Verjährungsbeginn, zwei Jahre; nur quantitatives Mindestmaß vor Mangelmitteilung, Schadensersatzausnahme und besondere Vereinbarungsvoraussetzungen gesondert.'), 'verbrauchsgut_gebraucht_mindestverjaehrung': (1, 'jahre', 'mindestens', '§476 Absatz2: gesetzlicher Verjährungsbeginn bei gebrauchter Ware, ein Jahr; Information/ausdrückliche gesonderte Vereinbarung und Schadensersatzausnahme gesondert.'), 'immobiliardarlehen_bedenkzeit': (7, 'tage', 'mindestens', '§495 Absatz3: Übergabe des Vertragsangebots im qualifizierten Fall ohne Widerrufsrecht nach Absatz2; mindestens sieben Tage Bedenkzeit.'), 'allgemeindarlehen_geberkuendigung': (2, 'monate', 'mindestens', '§499 Absatz1: Zugang der Geberkündigung bei unbestimmter Vertragslaufzeit; mindestens zwei Monate, keine gesamte Vereinbarungs-/Kündigungswirksamkeit.'), 'allgemeindarlehen_nehmerkuendigung': (1, 'monate', 'hoechstens', '§500 Absatz1: Zugang der Nehmerkündigung bei unbestimmter Rückzahlungszeit; vereinbarte Frist höchstens ein Monat, ohne Fristvereinbarung keine Wartefrist.'), 'zahlungsdienst_nutzerkuendigung': (1, 'monate', 'hoechstens', '§675h Absatz1: Zugang der Nutzerkündigung; vereinbarte Frist höchstens ein Monat, ohne Fristvereinbarung keine Wartefrist.'), 'zahlungsdienst_leisterkuendigung': (2, 'monate', 'mindestens', '§675h Absatz2: Zugang der Dienstleisterkündigung bei unbestimmtem Rahmenvertrag und vereinbartem Kündigungsrecht; mindestens zwei Monate.'), 'ueberziehung_laufzeit_504': (3, 'monate', 'hoechstens', '§504II: Auszahlung im qualifizierten Allgemein-Verbraucherdarlehen mit Überziehungsmöglichkeit; vereinbarte Laufzeit höchstens drei Monate nach Auszahlung. Nur numerischer Teil des Anwendungsbereichs. Alternative fristlose Kündbarkeit des Darlehensgebers und weitere Voraussetzungen zu Kosten, Zinsfälligkeit und Vertragsmitteilung gesondert; keine automatische Ausnahme sämtlicher Schutzvorschriften.'), 'agb_sonstige_maengel_mindestverjaehrung': (1, 'jahre', 'mindestens', '§309Nr8bff: sonstige qualifizierte Mängelfälle bei neu hergestellten Sachen/Werkleistungen, gesetzlicher Verjährungsbeginn und mindestens ein Jahr. Fälle438I2/634aI2 und andere strengere Regeln nicht auf ein Jahr reduzieren. Nur numerische Untergrenze, keine automatische Wirksamkeit oder Verlängerung einer unwirksamen Klausel.'), 'gastschulaufenthalt_dreimonatsdauer': (3, 'monate', 'mindestens', '§651uI: mindestens dreimonatiger qualifizierter Gastschulaufenthalt. Nur numerischer Dauertest; kürzere Aufenthalte oder Praktika können durch Vereinbarung ebenfalls erfasst sein. Schulbesuch/Gastfamilie/Aufnahmeland und weitere Voraussetzungen gesondert. Keine automatische Unwirksamkeit eines kürzeren Vertrags.'), 'agb_kuendigungsmonat_erstlaufzeit': (1, 'monate', 'hoechstens', '§309Nr9c: numerische Höchstlänge der Kündigungsfrist vor Ende der zunächst vorgesehenen Vertragsdauer. fristbeginn_am ist hier der vertraglich späteste Kündigungseingangstag, vereinbartes_ende_am der letzte eingeschlossene Erstlaufzeittag. Ab dieser Kündigungsgrenze darf höchstens ein Kalendermonat bis Tagesablauf des Vertragsendes liegen. Keine automatische AGB-Wirksamkeitsentscheidung; Klauselanwendbarkeit, Ausnahmen und Bedeutung der vereinbarten Termine rechtlich qualifizieren. Nicht die Kündigungsfrist einer anschließenden unbefristeten Verlängerung nachNr9b.'), 'kurzdarlehen_dreimonatsdauer_491': (3, 'monate', 'hoechstens', '§491II Nr3: qualifizierter Beginn der Rückzahlungsfrist als Ereignis, rechtlich vereinbarter spätester vollständiger Rückzahlungstag höchstens drei Kalendermonate später. Geringe Kosten sind zusätzlich rechtlich zu bewerten; keine erfundene EUR-/Prozentgrenze und kein automatischer Ausschluss sämtlicher Verbraucherschutzrechte. Nicht bloß erste Rate oder tatsächlicher freiwilliger Rückzahlungstag.')}

def verbraucher_vertragsfristgrenze(fristfall=None, fristbeginn_am=None, vereinbartes_ende_am=None, beginnart=None, einordnungsnachweis=None):
    """Quantitativer Fristvergleich, ohne automatische Heilung einer Vereinbarung."""
    _auswahl(fristfall, 'fristfall', tuple(_FAELLE))
    beginn = _datum(fristbeginn_am, 'fristbeginn_am')
    ende = _datum(vereinbartes_ende_am, 'vereinbartes_ende_am')
    _auswahl(beginnart, 'beginnart', ('ereignis', 'tagesbeginn'))
    _text(einordnungsnachweis, 'einordnungsnachweis')
    if ende < beginn:
        _fehler('vereinbartes_ende_am', 'Vereinbartes Ende darf nicht vor dem Fristbeginn liegen.')
    if not fristfall.startswith('verbrauchsgut_') and fristfall not in ('agb_sonstige_maengel_mindestverjaehrung', 'gastschulaufenthalt_dreimonatsdauer') and beginnart != 'ereignis':
        _fehler('beginnart', 'Dieser Fristfall setzt einen qualifizierten Ereignisbeginn voraus.')
    anzahl, einheit, richtung, fallhinweis = _FAELLE[fristfall]
    grenze = _frist(fristbeginn_am, anzahl, einheit, beginnart)
    innerhalb = ende >= grenze if richtung == 'mindestens' else ende <= grenze
    eingaben = dict(fristfall=fristfall, fristbeginn_am=fristbeginn_am, vereinbartes_ende_am=vereinbartes_ende_am, beginnart=beginnart, einordnungsnachweis=einordnungsnachweis)
    ergebnis = _ergebnis(dict(gesetzliches_grenzdatum=grenze.isoformat(), vergleichsrichtung=richtung, numerische_fristgrenze_eingehalten=innerhalb), 'datum_und_wahrheitswert', 'BGB_VERBRAUCHER_VERTRAGSFRISTGRENZE', eingaben, [dict(operation='Gesetzliche Mindest- oder Höchstdauer mit vorhandenem Kalenderkern berechnen und vereinbartes Ende einschließlich gegen Grenzdatum vergleichen')], eingaben.copy())
    ergebnis['annahmen'] = ['Rechtlich qualifizierter gesetzlicher Beginn/Erklärungszugang und Anwendungsfall; feste lokale BGB-Fassung.']
    ergebnis['hinweise'] = ['Nur numerische Vereinbarungsgrenze, kein automatisch wirksames Vertragsende oder vollständiger Verjährungsablauf. Unzulässige Vereinbarung wird nicht automatisch gekürzt oder verlängert. Kalender-/Hemmungskorrekturen und andere Wirksamkeitsgründe gesondert. Ende bezeichnet jeweils den letzten eingeschlossenen Tag bis Tagesablauf. Keine pauschale365-Tage-Jahresrechnung.', fallhinweis]
    return ergebnis
